const ACCOUNTS = [
  { instance: "gotosocial.lavender.spl.tech", username: "lavender" },
  { instance: "mastodon.social",              username: "Lavender_Daydream" },
  { instance: "gamerstavern.online",          username: "Lavender_Daydream" },
  { instance: "donphan.social",               username: "Lavender_Daydream" },
  { instance: "blorbo.social",                username: "Lavender_Daydream" },
  { instance: "urusai.social",                username: "Lavender_Daydream" },
  { instance: "plasmatrap.com",               username: "Lavender_Daydream" },
  { type: "bluesky",                          username: "lavender-daydream.bsky.social" },
];

// Fetches GTS post via RSS feed (no auth needed)
async function fetchGTS(inst, user) {
  const rssUrl = `https://${inst}/@${user}/feed.rss`;
  const res = await fetch(rssUrl);
  if (!res.ok) throw new Error(`RSS fetch failed: ${res.status}`);
  const text = await res.text();

  // Parse the XML response into something JS can read
  const parser = new DOMParser();
  const xml = parser.parseFromString(text, "application/xml");

  const item = xml.querySelector("item");
  if (!item) throw new Error("no posts in RSS feed");

  // Pull the data we need out of the RSS item
  const encoded = item.querySelector("encoded")?.textContent || "";
  const raw = encoded || item.querySelector("description")?.textContent || "";
  const content = raw
  .replace(/^@\S+\s+made\s+a\s+new\s+post:\s*/i, "")  // strips "@user made a new post: "
  .replace(/^"|"$/g, "")                                 // strips leading/trailing quotes
  .trim();
  const dateStr  = item.querySelector("pubDate")?.textContent || "";
  const link     = item.querySelector("link")?.textContent || "";
// Grab any image enclosures from the RSS item
  const enclosures = [...item.querySelectorAll("enclosure")]
    .filter(e => e.getAttribute("type")?.startsWith("image/"))
    .map(e => ({
      type: "image",
      url: e.getAttribute("url"),
      preview_url: e.getAttribute("url"),
      description: "",
    }));

  return {
    post: {
      content,
      created_at: new Date(dateStr).toISOString(),
      media_attachments: enclosures,
      url: link,
    },
    instance: inst,
    username: user,
  };
}

// Fetches a post via the standard Mastodon API (for all other instances)
async function fetchAPI(inst, user) {
  const { id } = await fetch(`https://${inst}/api/v1/accounts/lookup?acct=${user}`).then(r => r.json());
  const posts = await fetch(`https://${inst}/api/v1/accounts/${id}/statuses?limit=1&exclude_replies=true&exclude_reblogs=true`).then(r => r.json());
  if (!posts.length) throw new Error("no posts");
  return { post: posts[0], instance: inst, username: user };
}

// Fetches the latest Bluesky post via the public AT Protocol API (no auth needed)
async function fetchBluesky(user) {
  const url = `https://public.api.bsky.app/xrpc/app.bsky.feed.getAuthorFeed?actor=${encodeURIComponent(user)}&limit=5&filter=posts_no_replies`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`Bluesky fetch failed: ${res.status}`);
  const data = await res.json();

  // Skip reposts — getAuthorFeed includes them, marked with a "reason" field
  const feedItem = data.feed?.find(item => !item.reason);
  if (!feedItem) throw new Error("no posts");

  const record = feedItem.post.record;
  const embed  = feedItem.post.embed;

  let media_attachments = [];
  if (embed?.$type === "app.bsky.embed.images#view") {
    media_attachments = embed.images.map(img => ({
      type: "image",
      url: img.fullsize,
      preview_url: img.thumb,
      description: img.alt || "",
    }));
  }

  return {
    type: "bluesky",
    post: {
      content: record.text,
      created_at: record.createdAt,
      media_attachments,
      url: `https://bsky.app/profile/${user}/post/${feedItem.post.uri.split('/').pop()}`,
    },
    username: user,
  };
}

// Decides which fetch method to use based on the account type/instance
async function fetchLatest(account) {
  if (account.type === "bluesky") return fetchBluesky(account.username);
  if (account.instance === "gotosocial.lavender.spl.tech") return fetchGTS(account.instance, account.username);
  return fetchAPI(account.instance, account.username);
}

async function loadStatus() {
  const results = await Promise.allSettled(ACCOUNTS.map(a => fetchLatest(a)));

  let newest = null;
  results.forEach(r => {
    if (r.status !== 'fulfilled') return;
    if (!newest || new Date(r.value.post.created_at) > new Date(newest.post.created_at)) newest = r.value;
  });

  if (!newest) {
    document.getElementById('fedi-status').textContent = "couldn't load latest post.";
    return;
  }

  // Post text
  const tmp = document.createElement('div');
  tmp.innerHTML = newest.post.content;
  document.getElementById('fedi-status').textContent = tmp.textContent;

  // Meta line: @user@instance · date
  const date = new Date(newest.post.created_at).toLocaleString();
  const profileUrl = newest.type === "bluesky"
    ? `https://bsky.app/profile/${newest.username}`
    : `https://${newest.instance}/@${newest.username}`;
  const displayHandle = newest.type === "bluesky"
    ? `@${newest.username}`
    : `@${newest.username}@${newest.instance}`;
  const link = document.createElement('a');
  link.href = profileUrl;
  link.textContent = displayHandle;
  link.target = '_blank';
  const meta = document.getElementById('fedi-meta');
  meta.textContent = '';
  meta.appendChild(link);
  meta.append(` · ${date}`);

  // Media (API only — RSS doesn't provide these)
  const imageContainer = document.getElementById('fedi-images');
  imageContainer.innerHTML = '';
  for (const m of (newest.post.media_attachments || [])) {
    if (m.type === 'image') {
      const a = document.createElement('a');
      a.href = m.url;
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
      const el = document.createElement('img');
      el.src = m.preview_url;
      el.alt = m.description || 'image without alt text';
      a.appendChild(el);
      imageContainer.appendChild(a);
    } else if (m.type === 'video' || m.type === 'gifv') {
      const el = document.createElement('video');
      el.src = m.url;
      el.controls = true;
      el.loop = m.type === 'gifv';
      el.muted = m.type === 'gifv';
      el.setAttribute('aria-label', m.description || 'attached video');
      imageContainer.appendChild(el);
    }
  }
}

loadStatus();